scenario.en:
var ErrNotFound = errors.New("not found")

func repo() error  { return fmt.Errorf("repo: %w", ErrNotFound) }
func svc() error   { return fmt.Errorf("svc: %w", repo()) }
func sealed() error{ return fmt.Errorf("api: %v", repo()) } // note: %v

err := svc()

Q1: err == ErrNotFound — true or false?
Q2: errors.Is(err, ErrNotFound) — true or false, and through how many links?
Q3: errors.Is(sealed(), ErrNotFound) — true or false, and why?

